import type { Pool } from "pg";

export interface UserRow {
  id: string;
  name: string;
  email: string;
}

export async function searchUsers(pool: Pool, term: string): Promise<UserRow[]> {
  const result = await pool.query<UserRow>(
    `select id, name, email from users where name ilike '%${term}%' order by name limit 50`,
  );
  return result.rows;
}
